CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username varchar(32) NOT NULL UNIQUE, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(120) NOT NULL, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE project_memberships (project_id uuid NOT NULL REFERENCES projects(id), user_id uuid NOT NULL REFERENCES users(id), role varchar(20) NOT NULL CHECK (role IN ('owner','admin','member','viewer')), PRIMARY KEY(project_id,user_id));
CREATE TABLE integrations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), provider varchar(40) NOT NULL, external_account_id text, credential_ref text, status varchar(20) NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE artifacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), integration_id uuid REFERENCES integrations(id), source_type varchar(40) NOT NULL, external_id text, title text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(integration_id, external_id));
CREATE TABLE artifact_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), artifact_id uuid NOT NULL REFERENCES artifacts(id), version integer NOT NULL CHECK(version > 0), source_revision text, content jsonb NOT NULL, captured_at timestamptz NOT NULL DEFAULT now(), UNIQUE(artifact_id,version));
CREATE TABLE implementation_contracts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), artifact_version_id uuid NOT NULL REFERENCES artifact_versions(id), revision integer NOT NULL DEFAULT 1, interaction_spec jsonb NOT NULL DEFAULT '{}'::jsonb, state_model jsonb NOT NULL DEFAULT '{}'::jsonb, exception_scenarios jsonb NOT NULL DEFAULT '[]'::jsonb, permission_rules jsonb NOT NULL DEFAULT '[]'::jsonb, acceptance_criteria jsonb NOT NULL DEFAULT '[]'::jsonb, status varchar(20) NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workflows (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), name text NOT NULL, status varchar(20) NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE work_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), workflow_id uuid REFERENCES workflows(id), contract_id uuid REFERENCES implementation_contracts(id), title text NOT NULL, status varchar(20) NOT NULL DEFAULT 'draft', assignee_id uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE trace_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), artifact_version_id uuid REFERENCES artifact_versions(id), contract_id uuid REFERENCES implementation_contracts(id), work_item_id uuid REFERENCES work_items(id), relation varchar(40) NOT NULL, CHECK (num_nonnulls(artifact_version_id,contract_id,work_item_id) >= 2));
CREATE TABLE reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), work_item_id uuid REFERENCES work_items(id), reviewer_id uuid NOT NULL REFERENCES users(id), status varchar(20) NOT NULL DEFAULT 'pending', notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), review_id uuid REFERENCES reviews(id), actor_id uuid NOT NULL REFERENCES users(id), outcome varchar(30) NOT NULL, rationale text NOT NULL, decided_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE change_sets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), source_artifact_version_id uuid REFERENCES artifact_versions(id), summary text NOT NULL, status varchar(20) NOT NULL DEFAULT 'proposed', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE impact_analyses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), change_set_id uuid NOT NULL REFERENCES change_sets(id), findings jsonb NOT NULL DEFAULT '[]'::jsonb, assessed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agent_executions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), work_item_id uuid REFERENCES work_items(id), provider varchar(40) NOT NULL, status varchar(20) NOT NULL DEFAULT 'queued', input_refs jsonb NOT NULL DEFAULT '[]'::jsonb, output_ref text, evidence jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_artifacts_project ON artifacts(project_id);
CREATE INDEX idx_work_items_project ON work_items(project_id);
CREATE INDEX idx_agent_executions_project ON agent_executions(project_id);
